package io.github.diodeme.ji.host;

import java.util.Set;

/** Host authorization roles; Relay Owner is intentionally not a Host role. */
public enum HostRole {
    OBSERVER(Set.of("session:read")),
    CONTROLLER(Set.of("session:read", "session:write")),
    HOST_ADMIN(Set.of("session:read", "session:write", "host:admin", "credential:manage"));

    private final Set<String> scopes;
    HostRole(Set<String> scopes) { this.scopes = scopes; }
    public Set<String> scopes() { return scopes; }
    public boolean allows(String scope) { return scopes.contains(scope); }
}
